'use strict';

/**
* Method which return the default option.
*
* @private
* @name defaults
* @returns {Object} - out
*/
function defaults( ) {
	var out = {};

	// Boolean indicating whether to automatically re-render on a `change` event:
	out.autoRender = false;

	// Data which need to plot on x axis
	out.xAxisData = void 0;

	// Boolean indicate weather to enable auto adjustment on x axis or not
	out.xAxisAutoAdjustment = true;

	// Default background color code
	out.backgroundColor = 'Bwhite';

	// Default foreground color code
	out.foregroundColor = 'Fblack';

	// Default glyph code
	out.glyph = 'space';

	// Data
	out.data = [];

	// Category order
	out.categoriesOrder = 'original';

	// categories-format
	out.categoriesFormat = '%s';

	// Bar width
	out.barWidth = 5;

	// Bar gap
	out.barGap = 3;

	// Bars number
	out.barsPerLabel = 1;

	// Bars color
	out.barsColor = [ 'Fblack' ];

	// Xaxis formate
	out.xAxisFormat = '%s';

	// Xaxis data
	out.xAxisData = [];

	return out;
}

module.exports = defaults;
